# ============================================================
# 16_core12_GO_process_gene_overlap_visualization.R
# GSE303006 / GENCODE M23
#
# Goal:
#   Summarize leading-edge genes from representative GO BP
#   processes and visualize which genes are shared across
#   multiple processes as:
#     1) binary heatmaps (process x gene)
#     2) bipartite process-gene networks
#     3) process-process Jaccard-overlap networks
#
# Input files are generated by:
#   15_core12_GO_BP_reduce_redundancy_leading_edge_v2.R
#
# Default behavior:
#   - choose top 6 representative GO processes for POSITIVE
#   - choose top 6 representative GO processes for NEGATIVE
#   - keep genes appearing in >= 2 selected processes
#   - if too many such genes, keep top 40 by frequency
#
# Outputs:
#   Positive / negative:
#     - selected representative processes
#     - gene frequency tables
#     - process x gene binary matrices
#     - PDF/PNG heatmaps
#     - PDF/PNG bipartite networks
#     - process-process Jaccard matrices and networks
# ============================================================

# ============================================================
# 0. Settings
# ============================================================

POS_REP_FILE <-
    "GSE303006_M23_core12_GO_BP_positive_representative_top10.tsv"

NEG_REP_FILE <-
    "GSE303006_M23_core12_GO_BP_negative_representative_top10.tsv"

POS_LEADING_FILE <-
    "GSE303006_M23_core12_GO_BP_positive_top10_leading_edge_genes.tsv"

NEG_LEADING_FILE <-
    "GSE303006_M23_core12_GO_BP_negative_top10_leading_edge_genes.tsv"

TOP_N_POS <- 6L
TOP_N_NEG <- 6L

MIN_PROCESS_COUNT_PER_GENE <- 2L
MAX_SHARED_GENES <- 40L

OUT_PREFIX <- "GSE303006_M23_core12_GO"


